import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

// Custom Pair class for map key to handle (start, end) ranges
class RangePair {
    int start;
    int end;

    public RangePair(int start, int end) {
        this.start = start;
        this.end = end;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        RangePair rangePair = (RangePair) o;
        return start == rangePair.start && end == rangePair.end;
    }

    @Override
    public int hashCode() {
        return 31 * start + end; // Simple hash code combination
    }
}

class Solution {
    private Map<RangePair, List<TreeNode>> memo; // Memoization map

    public List<TreeNode> generateTrees(int n) {
        if (n == 0) {
            return new ArrayList<>();
        }
        memo = new HashMap<>(); // Initialize memoization map for each call
        return generate(1, n);
    }

    private List<TreeNode> generate(int start, int end) {
        List<TreeNode> res = new ArrayList<>();
        if (start > end) {
            res.add(null); // Represents an empty subtree
            return res;
        }
        if (start == end) {
            res.add(new TreeNode(start)); // Single node subtree
            return res;
        }

        RangePair currentRange = new RangePair(start, end);
        if (memo.containsKey(currentRange)) {
            return memo.get(currentRange);
        }

        for (int i = start; i <= end; i++) {
            List<TreeNode> leftTrees = generate(start, i - 1);
            List<TreeNode> rightTrees = generate(i + 1, end);

            for (TreeNode lTree : leftTrees) {
                for (TreeNode rTree : rightTrees) {
                    TreeNode root = new TreeNode(i);
                    root.left = lTree;
                    root.right = rTree;
                    res.add(root);
                }
            }
        }
        memo.put(currentRange, res); // Store result for future use
        return res;
    }
}

